		setCoffeeBeans: function(multiplier){
			console.log("set coffee beans to", multiplier);
			this.coffeeBeanMultiplier = multiplier;

		},
		
		rewardedVideoResult: function (isSuccess, source) {
			//add code after the rewarded video is displayed
			if (isSuccess) {
				if(source == 'SOCMED'){
					ig.game.gameController.showRewardSocMedBoost();
				}
				else if(source == 'ROAST'){
					ig.game.gameController.showRewardRoastBoost();
				}
			} else {
				ig.game.gameController.showRewardFailed();
			}
		},
		setupMarketJsGameCenter: function() {
			if(_SETTINGS) {
				if(_SETTINGS['MarketJSGameCenter']) {
					var el = ig.domHandler.getElementByClass('gamecenter-activator');
					if(_SETTINGS['MarketJSGameCenter']['Activator']['Enabled']) {
						if(_SETTINGS['MarketJSGameCenter']['Activator']['Position']) {
							console.log('MarketJSGameCenter activator settings present ....')
							ig.domHandler.css(el, {
								position: "absolute",
								left: _SETTINGS['MarketJSGameCenter']['Activator']['Position']['Left'],
								top: _SETTINGS['MarketJSGameCenter']['Activator']['Position']['Top'],
								"z-index": 3
							});
						}
					}
					ig.domHandler.show(el);
				} else {
					console.log('MarketJSGameCenter settings not defined in game settings')
				}
			}
		},
		finalize: function() {
            this.start();
                
			ig.sizeHandler.reorient();
		},
